/* GymDay – a short tip the first time each screen opens, and the Help page (v1.9).
   Tips: one card under the screen's title, in plain words, with "Got it" (never shown again on this phone) and
   "How it works" (the Help page at that topic). Help: every part of the app explained, as questions you can open.
   Which tips were dismissed is kept in Store.meta.tips (this phone only, not synced). Tests switch tips off with
   window.__tips = false. */
(function () {
  const A = window.App, S = window.Store;
  if (!A) return;
  const { $, esc, ACT, VIEWS } = A;
  const M = () => S.meta || {};
  const tipsOn = () => window.__tips !== false;

  // screen → [icon, title, text, help topic]
  const TIPS = {
    days: ['👋', 'This is Today', 'Tap Start ▶ to begin a workout. The round + adds food, weight or sleep.', 'start'],
    day: ['✏️', 'Changing a day', 'Drag ≡ to reorder, ✎ for sets and reps, ✕ to take an exercise out.', 'days'],
    choose: ['✅', "Pick today's exercises", 'Last time\'s exercises are ticked. Change anything, then Start.', 'workout'],
    session: ['🏋️', 'During a workout', 'Fill in the weight and reps, then tick ○. Drag ≡ to move an exercise.', 'workout'],
    library: ['📚', 'All the exercises', 'Search, or filter by muscle and equipment. Body map: tap a muscle.', 'library'],
    exercise: ['📈', 'One exercise', 'Your best set, your progress chart, a goal and your machine setup.', 'library'],
    history: ['📊', 'Your history', 'Every workout you saved. Tap one to see or change it.', 'progress'],
    calories: ['🍽', 'Food and calories', 'Search, scan or take a photo. Press and hold a food to move it.', 'food'],
    clubs: ['👥', 'Clubs', 'Start a club or join one with a code. You choose what club mates see.', 'clubs'],
    cooldown: ['🧘', 'Cool-down', 'Press Start: 30 seconds a stretch, and a buzz when it is time to switch.', 'workout'],
    settings: ['⚙️', 'Settings', 'Everyday settings are here. More features, your watch and backups are at the bottom.', 'start'],
  };
  // 1.35.2: a first-time tip on three screens only (Today, a workout, Food); the others were one "Got it" too many
  const SHOW = ['days', 'session', 'calories'];
  function tipHtml(name) {
    let t = TIPS[name]; if (!t) return '';
    if (name === 'days' && !(S.data.days || []).length) t = ['👋', 'This is Today', 'Make your first day below, or add the 5 starter days. The round + adds food, weight or sleep.', 'start'];
    if (name === 'session' && window.__calm !== false) t = ['🏋️', 'During a workout', 'Tap an exercise to start it, fill in the weight and reps, then tick ○. The last tick finishes it.', 'workout'];
    return `<div class="tip" data-tip="${name}"><span class="tip-ic">${t[0]}</span><div class="grow"><div class="tip-t">${esc(t[1])}</div><div class="tip-b">${esc(t[2])}</div>
      <div class="tip-row"><button data-act="tipOk" data-tip="${name}">Got it</button><button data-act="helpOpen" data-s="${t[3]}">How it works</button></div></div></div>`;
  }
  const after0 = A.afterRender;
  A.afterRender = name => {
    if (after0) after0(name);
    if (!tipsOn() || !TIPS[name] || (!SHOW.includes(name) && window.__tips !== true && window.__calm !== false) || (M().tips || {})[name]) return;
    const view = $('#view'); if (!view || view.querySelector('.tip')) return;
    const top = view.querySelector('.top, .session-top');          // under the screen's title (a workout: under its bar)
    if (top) top.insertAdjacentHTML('afterend', tipHtml(name)); else view.insertAdjacentHTML('afterbegin', tipHtml(name));
  };
  ACT.tipOk = el => {
    const m = M(); m.tips = Object.assign({}, m.tips, { [el.dataset.tip]: 1 }); if (S.saveMeta) S.saveMeta();
    const card = el.closest('.tip'); if (card) card.remove();
  };

  // ---------------------------------------------------------------- the Help page
  // [id, icon, title, [[question, answer], …]]
  const HELP = [
    ['start', '👋', 'Getting started', [
      ['What is a “day”?', 'A day is a list of exercises you do together, like “Chest & Triceps”. Make as many as you like with “+ New day” (on the Today page, above your days), or start from the five ready-made days.'],
      ['How do I start a workout?', 'Tap Start ▶ on a day, tick the exercises you will do today, then press Start. The workout keeps running even if you leave the app.'],
      ['Where is my data kept?', 'On this phone. Sign in at the top of Settings to keep a copy in your GymDay account too, so it is safe if you change phones and you can use clubs.'],
      ['The bottom bar', 'Today (your day at a glance, and your workout days), Food (what you eat, against your daily limits), Library (every exercise), Clubs, History (what you did and your progress) and Settings. Slide along the bar to switch quickly.'],
      ['The Today page (1.22)', 'The first tab. The big ring is what you have eaten against today’s target, with protein and what you burnt beside it. The small rings are last night’s sleep, how recovered your muscles are, and this week’s workouts against your goal. Tap any ring to open what is behind it. Under them: your next workout with Start ▶, then your days. With food tracking switched off, the big ring is your week’s workouts instead.'],
      ['The + button (1.22)', 'The round + above the bottom bar is on every tab. It adds food, a meal photo, a barcode, a dish eaten out, an activity, your body weight or last night’s sleep, or starts your next workout: one tap each.'],
      ['Search everything (1.22)', 'The 🔍 at the top of every tab opens one box that looks through foods (yours first), exercises, your days, past workouts, every setting, places in the app and this Help page. Tap a result to open the thing itself: a setting opens with its row lit up, a food opens its amount sheet for today.'],
      ['The ? on every screen (1.22)', 'Tap ? at the top of a screen to read what it is for and how each number on it is worked out. Tiles with a small ⓘ explain themselves when tapped. “What’s new” after an update lists what changed, each with a Show me button; it is also under Settings → About GymDay.'],
      ['The look: Glass or Classic (1.22)', 'Settings → Look → Style. Glass is the new look: frosted cards, glowing rings and bigger numbers. Classic is the look GymDay had before. Both work in dark and light, and with every text size.'],
      ['Text size and TalkBack (1.21)', 'Settings → Look → Text size: Same as phone follows your phone’s font size (Settings → Display on the phone); Small, Normal, Large or Extra large set it just for GymDay. Every screen also works with TalkBack, the phone’s screen reader: buttons, switches and the pop-up messages are read out, and a sheet that slides up is read first. Tap anywhere on a setting’s row to switch it on or off.']]],
    ['workout', '🏋️', 'During a workout', [
      ['Logging a set', 'Tap the kg box and type the weight on GymDay’s number pad, then the reps, and tick ○ when the set is done. Ticked sets are saved as you go.'],
      ['Voice logging (1.20)', 'Tap 🎤 at the top of the workout and say the set: “60 kilo 8 reps”, “60 for 8”, “8 reps”, or in Hindi “साठ किलो आठ बार”, or in Tamil “அறுபது கிலோ எட்டு தடவை”. The next set of the exercise in hand is filled in and ticked. “Done” or “same” ticks it as it is, “next” moves to the next exercise, “pause”, “resume” and “undo” do what they say. Pick the language in Settings → More features → During a workout. It uses your phone’s own speech recognition (Google’s), so GymDay needs no microphone permission.'],
      ['Warm-up sets (1.20, Trainer mode)', 'With Trainer mode on, a workout starts with a short ramp before the first big lift for each body part: about 40% × 10, 60% × 5 and 80% × 3 of your first working set (fewer steps for lighter weights), rounded to 2.5 kg and never under the empty bar. Only barbell, Smith, machine and dumbbell lifts of 20 kg and more get them. They are marked W: logged, but never counted for records or a muscle’s sets, and a warm-up left unticked is simply not saved. Undo in the message takes them out; Settings → More features → Warm-up sets turns them off.'],
      ['Cool-down stretches (1.20)', 'Once a set is ticked, 🧘 Cool-down stretches is under the exercises (and on the “Workout saved” sheet). It picks up to 8 stretches for the parts you trained, the most trained first: 30 seconds each (each side for one-sided ones), with a countdown, a buzz at each change, and Back, Pause and Skip. Ease in until it feels tight, never painful.'],
      ['The number pad', 'Its big keys fill the box you tapped. + and − change the weight by your usual step, Next jumps to the next box and ✓ Tick ticks the set. Prefer the phone’s keyboard? Switch off “Big number pad” in Settings → More features.'],
      ['Beating last time', 'Under each exercise you see what you lifted last time and a small target, like one more rep. Tap “Use” to fill it in.'],
      ['Adding a set or a drop set', '+ Set asks what kind of set: a normal set (the same weight and reps as the last one), a warm-up (logged, but not counted for records or for the muscle) or a drop set (the same reps, with the weight left empty for the lighter one). Don’t want the question? Switch off “Ask which kind of set when adding one” in Settings → More features → During a workout, and + Set adds a normal set straight away. You can also change any set’s kind by tapping its number.'],
      ['Changing the order of exercises (1.32)', 'Press and hold an exercise’s name (or its picture) for half a second, until the phone gives a small buzz, then drag it up or down and let go. While you drag, every exercise folds to one line so the whole workout fits on the screen; when you let go they open again as they were, and the numbers follow the new order. Moving first, before the buzz, scrolls the page as usual. The new order is only for this workout: your day keeps its own order (to change that, open the day and drag ≡). Moved by mistake? Tap Undo. It works when you edit a saved workout too, and ⋯ → Move up / Move down does the same with one tap.'],
      ['Moving a set up or down (1.21.6)', 'Hold a set’s number (1, 2, 3…) for half a second, then drag it up or down and let go. Everything moves with the set: the weight, the reps, the tick and its time, its label and how hard it was; the numbers follow. A quick tap on the number still labels the set, and that menu has ↑ Move up and ↓ Move down too. It works in History → Edit as well, and Undo puts the set back.'],
      ['Top set as you go', 'Tick a set heavier than your Top set (or the first one, if you have none) and Top set updates there and then, with a short message. Undo in the message unticks the set, in case the weight was a typo; fixing the weight moves Top set too.'],
      ['Timers and gym time', 'Each exercise has its own ▶ timer. Gym time counts the whole workout, without the time it was paused (⏸ at the top).'],
      ['Finishing', 'Press Finish, then Save workout. You see what you did, any records you beat and the muscles you worked, and you can say how it felt.'],
      ['Changing a workout afterwards', 'History → tap the workout → Edit. You can change sets, exercises, the date and the gym time.']]],
    ['days', '✏️', 'Days and exercises', [
      ['Changing a day', 'Tap the day. Hold ≡ and drag to change the order, ✎ sets how many sets and reps, ✕ takes an exercise out, + adds one.'],
      ['A plan for the week', 'Settings → More features → Weekly schedule gives each weekday a day, and the Today page shows what is on today.'],
      ['Weekly goal', 'Settings → Workouts → Weekly goal. The “This week” ring on the Today page fills as you train, and your streak counts the weeks you reached it. Tap the ring to change the goal.']]],
    ['library', '📚', 'The exercise library', [
      ['Finding an exercise', 'Search by name or muscle, or use the chips to filter by muscle group and equipment. “Body map” lets you tap a muscle to see exercises for it.'],
      ['Abs exercises (1.21.9)', 'The Library now has 108 abs and core exercises under Core: crunches and cable crunches, leg raises and knee tucks, sit-ups, rollouts, planks, twists, side bends, kettlebell windmills, slams and more. Each says which part it works most (upper abs, lower abs or obliques, shown on the body map), what it needs and how to do it. 82 have start and end photos; 19 well-known ones the photo set doesn\'t have (hollow body hold, L-sit, dragon flag, toes-to-bar, bird dog, Copenhagen side plank, Turkish get-up and more) have written steps, and their Video button searches YouTube. Build me a workout leaves out the ones that need a partner, unusual kit or an advanced skill until you have done one or starred it.'],
      ['A photo of a machine (1.20)', 'Library → 📷 Machine: take a photo of a machine, bench or rack in your gym. GymDay says what it is, which exercises in your library are done on it (with your own setup photos and notes for them), a few others, and how to set it up. Tap an exercise to open it. It needs your GymDay account and counts in the daily AI allowance.'],
      ['Top set and one-rep max', 'Top set is the heaviest set you have ticked. It updates by itself the moment you tick a heavier set, even if you never typed one, with a short message (Undo in it unticks the set, in case the weight was a typo). Warm-up sets don’t count, and nor does a workout whose numbers you chose not to keep. Discarding the workout puts Top set back. One-rep max is a number you type in yourself, if you know it, and never changes by itself.'],
      ['My setup', 'On an exercise’s page you can note your machine setup (seat height, pin number, grip). It shows under the exercise during a workout.'],
      ['Your own exercises', 'Library → “+ Custom” adds an exercise that is not in the list, with a picture if you like.']]],
    ['progress', '📊', 'Progress and records', [
      ['Insights and a day’s page (1.31)', 'Insights (the first tile in History’s Progress row, and “All insights” on Today’s Last 7 days card) shows your last 7 or 30 days side by side: a card for the day you’re looking at, with its numbers (sleep, workout, food, protein, steps, burnt, readiness, heart and weight), then one chart each for sleep, training, calories eaten, protein, steps, calories burnt, readiness, resting heart rate, HRV and body weight, and at the end those days in a few sentences. A chart only shows when those days have something for it. Swipe the day card left or right for the day after or before (1.35), slide a finger across the charts, tap a day, or use ‹ ›: the card and every chart then show that day, and a tap on the card (or Open) goes to its page. A dashed line is your target (the sleep you need, your calorie and protein targets); a small dot means nothing was logged that day. A day’s page tells the day in a few sentences, then has a card for each workout (time, sets, weight lifted against the last time you did that day, sets for each body part, and each exercise against the time before), your sleep the night before, food by meal, movement (an activity there opens when you tap it), readiness that morning and body weight. Swipe left or right for another day. You can also open a day from History: tap a day in the week strip or in the calendar. Every number is the same one that Today, Food, Recovery and History show.'],
      ['Safe, needs improvement, danger (1.35)', 'On Insights and a day’s page, the charts that have a healthy range show it as three soft bands: green is the safe zone, amber needs improvement, and red, the danger zone, is only for what is really low. Each band is named on the chart with its numbers. Sleep: the hours recommended for your age in green, up to 2 hours short in amber, more than 2 hours short in red. Calories eaten: green within a tenth of your target, amber under it down to what your body burns at rest, red under the resting burn; eating over your target is never marked. Protein: green at your target or more, amber down to the average a body needs (ICMR-NIN), red under it. Readiness: green from 60, amber 40 to 59, red under 40. Resting heart rate and HRV: against your own usual, amber between Recovery’s two lines and red past the second. A day’s number has ✓, ! or ⚠ beside it, so colour is never the only sign. GymDay gives general fitness information, not medical advice.'],
      ['Records', 'The best weight, reps and estimated one-rep max for each exercise. A small alert shows during a workout when you beat one.'],
      ['Sleep & heart (1.21.11)', 'At the top of Recovery: last night at a glance (time asleep against what you need, bedtime and wake time, deep, REM, light and awake sleep, your resting heart rate and HRV against your usual, and blood oxygen and breathing while asleep), then your last 7 or 30 nights. Add them with 📷 Screenshots of your watch app\'s sleep summary (read together, up to 10), or ✎ Type the numbers for any night; leave out what your watch doesn\'t show. Recovery counts last night\'s sleep, resting heart rate and HRV.'],
      ['Sleep from Today (1.35.2)', 'When last night isn’t in yet, tap Sleep on Today. Slide to how long you slept and tap Save, or use 📷 Screenshots: pick up to 10 screenshots of your watch app’s sleep (all its pages: the night, the stages, the heart), read together, and check them before they are saved. ⌚ From your watch brings last night in from Health Connect right away; if that isn’t set up yet, it shows how for your watch. Bedtime and more opens the whole form.'],
      ['Muscles, recovery and balance', 'Muscles shows the sets each muscle part got. Recovery shows which muscles are still recovering: green fully recovered, blue almost ready (65 to 99%), yellow recovering, red sore. Tap a muscle to see how recovered it is. Balance compares pairs, like push and pull.'],
      ['Body maps (1.20)', 'Every body map shows one big figure, twice the old size so each part is easy to tap. Front and Back above it turn it round; it opens on the side with more to see. Tap a part for its name and number.'],
      ['10 to 20 sets a week (1.20)', 'Muscles shows each body part’s hard sets this week against 10 to 20, the range many lifters aim for (the green band on each bar): under 10 says how many to go, 10 to 20 is green, over 20 is orange. A set counts fully for the exercise’s own part and half for each part that helps; warm-ups don’t count.'],
      ['What recovery counts', 'Recovery starts from your sets, how hard they were and the time since. It then counts: your sleep last night (type it, or add up to 10 screenshots of your watch’s sleep summary, read together with your resting heart rate and HRV; screenshots of your whole day on the Food tab count too), how your muscles feel (very sore, sore, nearly recovered or fully recovered, for the ones you trained; this comes first, for that day), protein and calories from the Food tab (yesterday, or the day before), your resting heart rate and HRV against your usual (once there are a few days of readings), and your age. A short night, little protein or food, or a resting heart rate above your usual make the times a little longer: What’s helping and what’s slowing says which, and by how much. A night without sleep cut muscle-building by about a fifth in one study, so even a very short night slows recovery by less than that. It is a guide, not a measurement.'],
      ['How sore you are (1.35.1)', 'GymDay works out how sore each muscle and each of its parts should be from your workouts: the sets, how hard they were, the time since, and whether the exercise or the muscle was new to you (new work makes you the most sore). Soreness is usually strongest 1 to 2 days after a workout and gone within about 5. Today shows it the day after a workout and the day after that: That’s right keeps it, and Change it lets you set each muscle to how you feel; GymDay spreads your answer over the muscle’s parts by how hard each one worked. To set each head or part yourself, turn on Settings → More features → Soreness for each part. Soreness also shows under each exercise during a workout, on Recovery, and part by part in Trainer mode, where Build me a workout goes easy on sore parts. Sharp pain, swelling or pain that keeps getting worse is not normal soreness: rest and see a doctor.'],
      ['Strength level', 'For the big barbell lifts, where your best stands for your body weight. Log your weight under Body weight first.'],
      ['Body weight and measurements', 'Log your weight and measurements to see them on a chart over time.']]],
    ['food', '🍽', 'Food and calories', [
      ['The Food tab', 'Food is the second tab in the bottom bar. At the top: today against your daily limits, then the overview of what is going well and what is missing. Then Add food, Photo, Scan and Eating out, your meals, your supplements, your day from your watch, the 7- and 30-day chart, your body weight and how what you burnt compares. The arrows at the top go back to earlier days.'],
      ['Everything in a food (1.20)', 'Tap any food on the Food tab and GymDay shows its calories, protein, carbs, fat and fibre, then sugars, saturated fat and salt, each with how much of your day it is. Vitamins and minerals open with one more tap, against what you need in a day. A meal from a photo, typed or a thali lists each of its foods too. ✎ at the top right changes it.'],
      ['Type what you ate (1.20)', 'In + Add food, ✍ Type it: write the meal, foods separated by commas, like “2 rotis, 1 katori dal, rice 1 cup, curd”, or tap 🎤 and say it (English, Hindi or Tamil). Each food is matched to the food list with the amount you typed (or its usual portion) and shown as lines you can check and change before saving, as with a meal photo.'],
      ['An amount in the search (1.35.2)', 'In + Add food you can type the amount with the food: “2 roti”, “100 g paneer”, “1 cup rice”, “milk 200 ml”. Each food found is counted for that amount: tap + to add it, or tap the food to change it. The search puts the everyday food first (tea is chai with milk and sugar, egg a boiled egg, rice cooked rice), and a food starts at an amount people eat: a teaspoon of sugar, 10 almonds, 100 g of chicken. On the amount screen the quick amounts fit the measure (rotis 1 to 4, grams 50 to 250), and typing “150 g” weighs it in grams.'],
      ['Thali (1.20)', 'In + Add food, 🍛 Thali: South Indian meals, North Indian, Gujarati, Bengali or Maharashtrian. Tick what was on your plate, + and − for how much (a refill is one more), then check and save. Every number is the food list’s.'],
      ['Tomorrow’s meals (1.20)', 'On the Food tab, 📅 Plan tomorrow’s meals makes a day of everyday Indian meals sized to your calories and protein: veg, veg with eggs or non-veg. ↻ Swap changes one meal. Tomorrow the plan is on the Food tab, and Log it adds a meal (change anything you ate differently first).'],
      ['Smart calorie target (1.20)', 'After 3 weeks with at least 4 weigh-ins and 10 days of food logged, GymDay works out what your body really uses: what you ate, less what your weight change stands for (about 7,700 kcal a kg). When that is 100 kcal or more away from its own estimate, the Food tab suggests a new target (at most 250 kcal at a time; under 18 it never lowers it much). Nothing changes until you tap Use. It is only as right as your log. Settings → More features → Smart calorie target turns it off, and the target goes back to the formula.'],
      ['Caffeine (1.20)', 'Caffeine is the fourth bar under Stay under. Foods from the US tables count their own caffeine; others count by their name with the US number for the same drink (a cup of chai about 30 mg, filter coffee with milk about 55, an espresso about 60, a can of Red Bull 80). The limit is 400 mg a day for adults (US FDA, EFSA, Health Canada); under 18 it is 2.5 mg for each kg you weigh (Health Canada). Tap the bar for the day’s foods.'],
      ['Supplement and protein reminders (1.20)', 'Open a supplement in Supplements and switch on Remind me: a notification at that time on the days it is due (it starts from the time you picked under When). The evening protein reminder (Settings → More features → Food, 7 pm unless you change it) tells you how much protein is left when food is logged and you are 10 g or more short.'],
      ['The Food widget (1.20)', 'Long-press your home screen → Widgets → GymDay → GymDay food: today’s calories and protein against your targets, and + Add food. It starts a new day at midnight by itself.'],
      ['Your daily limits', 'Fill in your weight, height, age, body, how active you are outside the gym and your goal once on the Food tab. GymDay works out your calories the way ICMR-NIN’s Nutrient Requirements for Indians (2020) does, for ages 10 to 100: for adults from your basal burn (lowered for Indians) times how active you are (mostly sitting, lightly active, active or very active), and for 10 to 18 years with the method ICMR-NIN keeps for growing children, which counts the energy growing takes. Workouts and activities are added on top. From the calories come protein (1.6 g for each kg you weigh, the amount for someone who trains, never under ICMR-NIN’s minimum), fat (about 27% of calories), carbs (the rest, 45 to 65%) and fibre (15 g for each 1,000 kcal). Reach: protein and fibre turn green when you get there; carbs and fat turn amber well past their target. Stay under: sugars (90 g in a 2,000 kcal day, milk and fruit sugar included; ICMR-NIN asks to keep added sugar under 5% of calories), saturated fat (under a tenth of your calories) and salt (5 g); they turn amber when you go over. Under 18, a cut is kept small. Change it any time with Change. Tap any bar to see its target, how it is set and the day’s foods that gave it.'],
      ['Where the numbers come from', 'Each food shows a badge: Checked label (the maker’s or chain’s own numbers), Food table (a government food table), Worked out by GymDay (a version worked out from the tables, with a note saying how), Calories from the chain, the rest estimated, Estimate from a nutrition database, Packet typed in by shoppers (Open Food Facts), AI estimate from a photo, Found online, or Typed by you.'],
      ['Weighing your food', 'With a kitchen scale, turn on ⚖ Weigh in grams in a food’s amount sheet: new foods then start in grams, so you type what the scale says. Foods you have logged before open the way you logged them last. On a meal photo, type the grams you weighed next to a line and its numbers follow.'],
      ['Body weight and the weekly report', 'Log your weight on the Food tab (+ Weight) about once a week, at the same time of day: its line shows whether your target is working. On Sundays and Mondays a Your week card shows the week’s averages against your limits, your best day and your protein streak; Weekly report under the chart opens it any day.'],
      ['Adding food', 'On the food page, + Add food (or + Add on a meal). Search about 30,000 foods, including many Indian dishes and about 8,900 Indian packets, then pick how much: katori, cup, piece, grams and more. Indian names work too: elaneer or nariyal pani, ganne ka ras, chaas, bhutta, jamun, sitaphal.'],
      ['Fresh Indian foods', 'Tender coconut water (by the coconut) and malai, sugarcane juice, juice-stall juices, nimbu pani and fresh lime soda, chaas, lassi, sol kadhi, falooda and more, each sweet, salted or with no sugar where stalls make it different ways. Street snacks made fresh (bhutta, fruit chaat, roasted chana and peanuts, jhal muri) and Indian fruits, mango and banana kinds. Their numbers come from ICMR-NIN’s Indian Food Composition Tables 2017 where it measured them; the rest are worked out from it, with a note saying how.'],
      ['Versions of a food (ⓘ)', 'Foods marked GymDay are versions of a food made different ways, such as biryani with seeraga samba rice or ragi roti. The ⓘ note under the name says which food table the numbers come from or how they were worked out.'],
      ['Eating out', 'On the food page, 🍽 Eating out. Take a photo of your plate first: the AI is told it was a restaurant meal, with bigger portions and more oil. Or pick from 165 restaurant dishes by cuisine, served at restaurant portions (half, full, katori), or from the chains: McDonald’s, KFC, Burger King, Subway, Starbucks, Pizza Hut, La Pino’z, Wow! Momo, Third Wave Coffee and a few Domino’s estimates, from the chains’ own numbers where they publish them. Add the place you are eating at: what you eat there is kept with it, so next time the same plate is one tap.'],
      ['A dish that isn’t in the app', 'In Eating out, search for it and tap Look it up on the web (or Not here? at the bottom). Type the dish and the restaurant: GymDay’s server searches the web (Google, through the server’s AI key) and shows the calories, protein, carbs and fat for one serving, with the pages they came from and which numbers are estimates. If nothing turns up, take a photo of it instead.'],
      ['Counting pieces', 'For curries with meat, fish, egg or paneer, fried or grilled pieces and biryani, choose By pieces: how many pieces, small, medium or large, bone-in or boneless, and how much gravy or rice. The pieces and the gravy are counted apart.'],
      ['Moving food to another meal', 'Press and hold a food for about half a second, then drag it onto another meal. Carry it to the top or bottom edge and the page scrolls, faster the closer you go; move back off the edge to stop. Or tap the food and pick the meal under Move to. Undo is in the message that pops up.'],
      ['Photos of a meal or a label', 'Take a photo and the AI reads what is in it. Up to 4 photos of the same meal or packet are read together, as one: different dishes of one meal, or the front and the back of a pack. Pick several at once from the gallery, or tap + Add another photo after the first. If it can’t tell, it asks up to 3 quick questions first; you can always skip and fix the numbers yourself. This needs the AI key on the GymDay server. Since 1.26 the AI works out, for each food, what it is, how many grams there are and what 100 g of it holds (protein, carbs, fat, fibre); the calories are then calculated from those, never guessed: 4 kcal for a gram of protein or carbs, 9 for fat, 2 for fibre. A packet whose nutrition table can be read is copied from the table instead. The line says where its numbers are from, and Food list › swaps it for a food from GymDay’s own list (eaten out, the restaurant version of a dish; at home, the home-made one). A line the AI could not work out is counted from the food list as before; when the app isn’t sure which food in the list it is, the line says “Check this”: tap it to pick from the closest foods or search the list. Vitamins and minerals still come from the food list’s closest food. Change a line and its numbers follow: a new name and the AI reads the same photo again and works the new food out the same way (or, without internet, the food list is used); a new amount in the name (Roti, 3) scales it, grams too; new grams change every number; new calories keep the protein, carbs and fat in step and move the grams with them; new protein, carbs or fat change the calories. This works before and after saving.'],
      ['Protein powders and creatine', 'Search the brand or just “whey”, “creatine” or “yeast protein”. About 30 products, such as Happy Cultures, MuscleBlaze, ON, Nakpro, Myprotein and Amul, use their makers’ own label numbers per scoop. A scoop of creatine adds to the day’s creatine. If yours isn’t there, take a photo of its label.'],
      ['Salt in your food (1.21.7)', 'Tap Sodium (or the Salt bar on the Food tab) and pick how much salt goes into your home cooking: No salt (only what the ingredients have), Less, Usual (as much as typical Indian recipes) or More. It changes the sodium of home-cooked dishes from the food list, not food eaten out. One dish can have its own: tap it on the Food tab, then Salt. ORS (Electral and other WHO-formula sachets) now counts all its sodium, about 1,720 mg a sachet, and its potassium; it is meant to be salty when you have lost salt in sweat or with diarrhoea.'],
      ['Rice dishes from photos (1.21.5)', 'A photo line like “rice with soya chunks and vegetables”, “rice with sambar”, “rice with curd” or “rice with ghee” is now counted as that rice dish from the food list (soya chunks rice, sambar rice, curd rice, ghee rice), not as plain rice. Salt, lemon or vegetables in general still mean plain rice. Your past photo meals are recounted once with this, and the change is shown with Undo.'],
      ['Soya chunks (1.21.4)', 'Search “soya” or “meal maker”: Nutrela soya chunks with their label numbers (weigh them dry), soya chunks soaked and boiled (about 3 times the dry weight), soya granules, and 17 home dishes: curry, dry fry, chilli, manchurian, soya 65, biryani, pulao, fried rice, keema, bhurji, aloo soya, soya matar, butter masala, cutlet, tikka, paratha and salad. Each dish’s ⓘ note gives its recipe.'],
      ['Fizzy drinks and soda (1.21.3)', 'Search a drink by its name: Lehar Evervess and Bisleri soda, Kinley, Schweppes, RimZim, Lahori Zeera, Bindu Jeera, Coca-Cola, Thums Up, Pepsi, Sprite, Limca, Fanta, 7UP, Mountain Dew, Campa, Red Bull, Monster, Sting and more, 35 in all. Each one uses the numbers its label prints for 100 ml, from the maker’s website where it has them, otherwise a shop’s copy of the label. Pick a glass, can or bottle, or type the ml. Sugar and sodium count toward your day, and so does caffeine for colas and energy drinks. Scanning one of these cans or bottles opens the same checked label.'],
      ['Snacks', 'For a snack the AI can’t place, it asks whether it is homemade or packaged, the oil it was fried in, whether it was fried or baked, and how much you ate. For a packet it can read, it uses that product’s numbers and counts only what you ate.'],
      ['Barcodes', 'Scan a packet’s barcode. About 8,900 Indian packets from Open Food Facts are in the app, so most scans work without internet; others are looked up online. A scanned product is kept in My foods, so the next scan works offline too.'],
      ['A serving or the whole packet (1.21.1)', 'A packet’s label gives its numbers per serving, not for the whole packet. For packaged foods GymDay shows two choices at the top: Per serving and Whole packet, with a line saying exactly what you are adding (for example 1 serving, 25 g, not the whole packet, 50 g). When the label doesn’t say how big the packet is, tap Whole packet and type the weight printed on it once: GymDay keeps it for that food. Next time it starts on what you picked last.'],
      ['Protein and creatine', 'Pin your supplement at the top of the food page (photo of the label, barcode or typed). One tap then adds a serving; once you have had one that day, − on the card takes one back. On the Supplements and vitamins card, − next to a taken one takes back one dose.'],
      ['Supplements', 'On the food page, Supplements and vitamins › Manage (or + Add). Pick your multivitamin, omega-3, vitamin D, zinc, B12, iron, calcium and more from about 115 products of 34 brands (each checked against its label) or a plain one by its dose, or take a photo of any label. Say how much, how many times a day and how often (every day, every other day, some days, once a week). Each day it is due counts as taken; tap it to untick a day you skipped, or use − and + if you took more or less.'],
      ['Vitamins and minerals', 'Vitamins and minerals (from the food page or the Vitamins tile in Progress) adds up 26 vitamins and minerals from your food and supplements. Omega-3 is one line, on the Food tab card as on the Vitamins page: whichever kind is nearer its need counts. Tap it to see the split between plant omega-3 (ALA, from flax, chia, walnuts or a veg omega-3 capsule) and omega-3 from fish or algae (EPA and DHA), each against its own need. A flax seed oil capsule is about half omega-3: 1000 mg of oil gives about 0.53 g. All are shown as a % of your daily need from ICMR-NIN 2020 for your age and sex (About me). ⚠ marks anything above the safe upper limit; tap a line to see where it came from. Photo meals count each food the AI saw, at its grams; a typed food counts the list’s food of the same name, for the grams its calories make. Many savoury home recipes in the Indian tables leave the salt out, so those dishes count typical home salt (about 166 mg of sodium in 100 g, the middle of the tables’ salted dishes). The overview asks once whether you cook with less, usual or more salt: about 30% less or 60% more sodium in those dishes (not in food eaten out). No numbers yet means none of the foods counted has a number for it.'],
      ['Daily target', 'Your daily limits (above) are your target. Change on the target card lets you pick another goal or type your own numbers.'],
      ['Eaten and burnt', 'Eaten is what you logged. Burnt is your workouts and activities (from your watch, typed, screenshots or estimated), and your everyday burn too if you choose that in Settings. The everyday burn already counts every minute of your day at your usual pace, so a workout or an activity adds only what it burnt beyond that: you see it as “adds …” next to each one. When you add screenshots of your whole day (Your day, from your watch), Burnt is your watch’s total for that day instead, because your workouts are already in it.'],
      ['Eaten, Burnt and your target (1.21.10)', 'Tap Eaten on the Food tab to see what made up the day: protein, carbs and fat with their share of the calories, the foods that gave the most, and each meal with its foods (tap one to see everything in it or to change it). Tap Burnt to see what it is made of: your everyday burn (your body at rest plus a normal day\'s moving about) and what each workout and activity added, or your watch\'s numbers; + Add an activity there (1.21.12) adds a sport, a walk or a swim by typing its calories, a photo of your watch, or how long and how hard. The line under your daily target says how it is worked out: your usual day (the everyday burn plus what your workouts and activities added over the last 14 days, as an average a day) plus 300 kcal to gain muscle, or less to lose fat. It stays the same on rest days on purpose; Burnt is what changes with each day.'],
      ['What a workout adds (1.21.8)', 'Your everyday burn already counts every minute of the day, gym time included, at your usual pace. So a workout adds what it burnt beyond that: if your everyday burn is about 110 kcal an hour, a 1-hour workout of 300 kcal adds about 190. On the Food tab, under Burnt, each workout says how much of it the everyday burn already counts and what it adds, and its own Calories burnt card explains it. If you add your whole day from your watch during the day, its numbers count up to the time you added them: the rest of the day counts at your usual pace, and workouts and activities after it are added. Took the screenshots earlier? Tap Your watch under Burnt and set the time they show, or mark them as the whole day.'],
      ['Sports and other activities', 'On the Food tab, under Burnt, tap + Add an activity and pick what you did: cricket, football, badminton, kabaddi, a walk, a swim, yoga, dance and about 100 more (search, or browse by kind). Then say when it started and how long it was, and give the calories one of three ways: Work it out (say how hard you played, from Easy to All out, and how tired you feel; for running, walking, cycling, swimming and skipping you can pick your speed instead), Type them (what your watch or app showed, and whether that is its total or its active calories; not sure counts it as total), or 📷 Watch photo (up to 10 screenshots of the activity’s summary, read for you). How much energy each sport takes is from the 2024 Adult Compendium of Physical Activities; games it doesn’t list, like kabaddi or kho-kho, are counted like the closest game it does, and the sheet says which. Nothing is counted twice: only what the activity burnt beyond your everyday burn is added, and on a day counted from your watch’s whole-day total the app asks whether the watch was on (if it was, the activity is already in that total). Tap an activity on the Burnt card to change or delete it. In Settings › More features › Food (or at the bottom of Add an activity) you choose where activities show: on the Food tab only, also in History, or in History and toward your weekly goal (each one of 20 minutes or more counts as a workout).'],
      ['The overview', 'Under your daily limits, the overview says in a few lines what is going well, what is missing, what is over a limit and which foods to cut down, for today or the last 7 days (Today / 7 days). Tap it for all of it: for what is missing it suggests everyday foods that fit what you eat, with how much each adds; for what is over it names the foods behind it, how much half a portion saves and a swap. Before 8 pm, today’s missing things are “still to go”. It is worked out by the app from what you logged, so log everything, and treat it as a guide over days rather than an exact count for one meal.'],
      ['What you eat and your oil', 'The first time you open the Food tab, GymDay asks whether you are vegetarian, vegetarian with eggs or non-veg (for the foods the overview suggests), and how much oil your home cooking uses: more oil adds about 3 g of fat to 100 g of curries, dals, sabzis, rice dishes and parathas from the Indian list, less takes off up to 2 g. Change either one at the bottom of the overview.'],
      ['Leftovers', 'Left some of a meal? In the meal’s ⋯ menu (or on a meal photo), tap Leftovers. Take a photo of the plate (the AI compares it with the meal’s own photo when there is one), or type the grams left of each food from your kitchen scale, or weigh all the leftovers together and GymDay splits them between the foods. A Leftovers line in the meal then takes off their calories, protein and the rest, vitamins included. Tap it to change or remove it.'],
      ['Easy to forget', 'If you logged plain chai or coffee, the overview asks about sugar; if you logged rotis without ghee or butter, it asks about that. One tap adds a teaspoon to the same meal (Undo in the message). If you never take sugar or never add ghee, tap I don’t take sugar or I don’t add any and it stops asking.'],
      ['Your day, from your watch', 'On the Food tab, Your day, from your watch › Add screenshots: pick up to 10 screenshots of your watch app’s summary for the day (Samsung Health, Google Fit, Fitbit, Garmin and others): steps, calories, heart rate, sleep. The AI reads them together and GymDay shows the day as a picture and a few plain sentences: steps against the usual bands, what you burnt as everyday food (a medium chapati is about 100 kcal) and eaten against burnt. If the screenshots show another date, it offers to save them to that day. Tap the card for all the numbers, new screenshots or Remove.'],
      ['Workout screenshots', 'After a workout, on the Calories burnt card, tap 📷 Screenshots from your watch or app and pick up to 10 screenshots of its summary: calories, heart rate, zones, time, steps. The AI reads them together, then GymDay shows how hard it was on a gauge with a few plain sentences, and what you burnt as everyday food: your average heart rate as a share of your maximum (208 − 0.7 × your age, or the highest your watch has recorded if that is higher), on the American College of Sports Medicine’s scale (very light under 57%, light 57–63%, moderate 64–76%, vigorous 77–95%, near-maximal from 96%), your time in each zone, and how hard it was at its hardest. All the numbers has the rest: your burn rate and how it compares with your last workouts. Only the numbers are kept, not the pictures. Tap the card again to see it or remove it. You can add them later too: for 12 hours after a workout with no calories, Days shows Add your watch’s screenshots?, and such workouts have a 📷 in History.']]],
    ['clubs', '👥', 'Clubs and your account', [
      ['Report and block (1.30)', 'In a club, “report” under a message, ⚑ on a comment, or Report on a person’s page sends it to the person who looks after GymDay, who can take it down and take people out of clubs. Block on a person’s page hides their messages, comments and workouts from you; they are not told. Settings → Account → Blocked people undoes it. An AI answer (a meal photo, an order, a program) can be reported too, with ⚑ Report this AI answer.'],
      ['Signing in', 'Settings: the card at the top. Type your email and the 6-digit code it sends you. There is no password.'],
      ['Clubs', 'Start a club and share its code, or join one with a code. You see each other’s workouts, records and chat.'],
      ['What club mates see', 'You choose on the Account page (Settings, then tap your name at the top): a summary, everything, or nothing. Food and body measurements are never shared.']]],
    ['watch', '⌚', 'Your watch and Google Health', [
      ['No watch? (1.33)', 'Settings → Watch → switch off “I have a smartwatch or band”. Everything that needs a watch is then hidden and paused: Sleep from your watch, Watch & Google Health, the watch’s screenshots, and resting heart rate, HRV, blood oxygen and breathing. Sleep stays, typed by hand, and so do activities and calories. Nothing you logged is deleted: switch it back on and every number is where it was. A new phone asks once, at the end of the short tour.'],
      ['Heart rate and calories', 'Settings → Watch & Google Health → Connect. GymDay reads the heart rate and calories your watch recorded during each workout from Health Connect.'],
      ['Putting workouts in Health Connect', 'Switch on “Put my workouts in Health Connect” there, and each saved workout is added for other apps to see.']]],
    ['data', '💾', 'Backups and your data', [
      ['Making a backup', 'Settings → Backup & export → Export backup saves everything in one file. Keep it on Drive now and then.'],
      ['A spreadsheet', '“Export to a spreadsheet” gives every set you logged, for Google Sheets or Excel.'],
      ['Moving to a new phone', 'Sign in to your account on the new phone, or import your backup file there.']]],
    ['trouble', '🛠', 'If something looks wrong', [
      ['The phone’s keyboard opens over the number pad', 'Update to the newest GymDay. If it still happens, switch off “Big number pad” in Settings → More features to use the phone’s keyboard instead.'],
      ['A photo isn’t read', 'Photos and screenshots are read on GymDay’s server by Claude, an AI made by Anthropic. This needs you signed in, online, and “Let AI read photos” on in Settings → More features (GymDay asks the first time). If it is busy or slow, try again in a minute or type what you ate. The photo is kept with the meal either way.'],
      ['Who reads my photos', 'Only the photo, screenshot or words you choose are sent: to GymDay’s server, which asks Claude (Anthropic’s AI) what they show, and sends the answer back. GymDay’s server doesn’t keep them. Turn it off any time in Settings → More features → Let AI read photos; everything can still be typed by hand. About → Privacy policy has the details.'],
      ['My other phone doesn’t show a workout', 'Settings → Account → Sync now on both phones. You need to be signed in to the same account.'],
      ['Tips', 'The tips at the top of each screen can be shown again: the button is at the bottom of this page.']]],
  ];
  // 1.23: more to each topic
  const MORE = {
    start: [
      ['GymDay’s own dropdowns (1.28)', 'A box with a ⌄ opens GymDay’s own list right under it, with a ✓ on what is chosen, instead of the phone’s grey box. Tap a choice to pick it; tap outside or press back to leave it as it was.'],
      ['Arrange your Today page (1.27)', 'Under the cards on Today, tap ⇅ Arrange this page (or Settings → More features → Arrange the Today page). Drag ≡, or use ↑ and ↓, to change the order; switch a card off to take it off Today. What a card does stays on: switching off Recovery there only hides its card. Back to the usual puts everything back. The cards above your days are arranged; the workout in progress stays on top and your days stay below.'],
      ['The new look on other pages (1.27)', 'The short choices on other pages are pills too: what Calories burnt counts, how long a busy-week workout is, and cm or inches for measurements. Every other drop-down box shows its choice in bold with a small arrow, the same as on the Settings pages.'],
      ['The new Settings (1.26)', 'Settings has a new look and nothing was taken out. Your picture, name and the saving line are at the top: tap that card for the Account page, where your name, your picture, what club mates see, Sync now, Sign out and Delete my account now are. Under it, each row has an icon and shows what it is set to. Two or three choices are pills you tap (kg or lb, Dark, Light or Auto); a longer list is a small box that opens your phone’s own list. More features, Watch & Google Health, Backup & export, Help and About are the rows at the bottom, in the same look.']],
    workout: [
      ['Harder bodyweight moves (1.28)', 'With Trainer mode on, a card on Today says when a bodyweight move has got easy: about 3 × 15 knee push-ups, push-ups, decline push-ups or bench dips, 3 × 12 inverted rows, or 3 × 8 chin-ups. It offers the next harder move (knee push-up → push-up → decline push-up → archer push-up; bench dip → dips; inverted row → chin-up → pull-up), starting at fewer reps. Switch in my plan swaps it in your days; Not yet asks again after your next workout of it. Your history of the old move stays.'],
      ['Do a club mate’s workout (1.28)', 'In a club, open a club mate’s workout (they need to share everything) and tap Do this workout. It becomes one of your days with their exercises, sets and reps; the weights are your own (an exercise you haven’t done yet starts empty). An exercise that isn’t in your library is left out and named.'],
      ['Import a program (1.28)', 'Days → Import a program: a photo of a gym whiteboard or a printed plan, a screenshot of a post, or pasted text. The AI reads the days, exercises, sets and reps, and GymDay matches each exercise to its library (an exercise not there is added as your own). Look the days over, leave any out, then Add. A range like 8–12 becomes the exercise’s rep range unless it has one. One AI read.'],
      ['Forgot to log? Ask my watch (1.28)', 'Settings → More features → Forgot to log? Ask my watch, then allow Exercise in Health Connect. When your watch recorded a gym session (strength training, weightlifting or calisthenics) and GymDay has no workout near that time, GymDay logs it as the day that was due then, with the weights and reps of its last time, marked “Not recorded in GymDay · estimated”. It shows it to you and asks whether your weights changed: No keeps it, Yes opens it to change. It looks back 7 days, at most once an hour; it can be removed if it wasn’t a gym workout.'],
      ['Your weekly sets per body part (1.27)', 'History → Progress → Muscles → Set targets. For each body part, how many sets a week you want: 2 to 30, 10 to start with (many lifters aim for 10 to 20). The Muscles page then shows each body part against your own target, and Balance my week adds sets for the ones still under theirs. All back to 10 undoes it.'],
      ['Plateau plan (1.27)', 'When an exercise has not gone up in 4 weeks (Stuck alerts), its card on Today and its own page offer a 3-week plan. Week 1 is a lighter week at about 90% of the weight you were stuck at, same reps. Week 2 adds one more set at that weight. Week 3 goes one step heavier, same reps. The weeks are calendar weeks from the one you start in, and the line under the exercise in a workout says which week it is. While the plan runs it sets the weights instead of auto-progression; Stop on the exercise’s page ends it.'],
      ['Auto-progression (1.25)', 'Only while Track reps is on. Open an exercise’s page and set a rep range under Auto-progression, say 8–12 (or tick the box to use it for all your weight exercises at once). You stay at one weight until every working set at your top weight reaches the top of the range. The next workout then starts one step heavier (2.5 kg, or 5 lb), back at the bottom of the range, and a green line says so. Undo on that line puts last time’s weight back. Until you get there, the line says what to aim for. It does not raise the weight in an easy week.'],
      ['Busy week (1.25)', 'For weeks when school, exams or work take over. On the screen where you tick today’s exercises, tap ⚡ Busy week (or switch it on in Settings → More features). Until Sunday, GymDay ticks a short version of each day for you: the first exercise of every body part the day trains, then whatever else fits in 20, 25 or 30 minutes, with 2 working sets each at your usual weights. Fewer sets at the same weight is what keeps strength. Tick more if you have time. Your numbers are saved as usual, and the full number of sets comes back by itself afterwards.'],
      ['Balance my week (1.25)', 'History → Progress → Muscles, this week. When a body part you train will end the week under 10 sets, even counting what is still planned, a card offers to add a few sets for it: 2 for each body part first, at most 4 extra sets a workout. Tap Add them and they appear in your next workout this week, as extra sets of an exercise already in it or as an exercise added for that day, marked ⚖. They are not added in a busy or an easy week, and the offer ends with the week.'],
      ['Form cues (1.25, Trainer mode)', 'With Trainer mode on, each exercise in a workout shows one short reminder in big letters, such as “Elbows still, no swing”. GymDay has one for every kind of movement. Tap the cue to write your own for that exercise: the thing you most often forget.'],
      ['Focus: one exercise at a time (1.23)', 'In a workout, tap ◎ Focus in the bar under the timer. One exercise fills the screen with big numbers; the dots and ‹ › (or a swipe left or right) change exercise, and one big button says what comes next: Start, Done (which moves on to the next exercise) or Finish. It follows the exercise you are timing. ☰ List goes back to the full list. GymDay remembers which one you used, on this phone.'],
      ['The next set (1.23, Trainer mode)', 'With Trainer mode on, a line appears under the set you just ticked: “Next set: 52.5 kg × 8”. It comes from that set and how hard you said it was. Easy: one step heavier. 2 more in me: the same again. 1 more: the same weight, one rep fewer. All out: about 8% lighter so you keep your reps. Tap Use to fill it in, or type what you like; tap the words to read how it is worked out. Warm-up and drop sets are left alone.'],
      ['“Is this right?” (1.23)', 'GymDay asks before it ticks a set whose weight is far above your heaviest so far (more than half as much again, and at least 20 kg more), far below your usual, or with more than 60 reps: usually a slipped decimal, like 525 for 52.5. “Yes, tick it” keeps it exactly as typed; “Change it” puts you back on the box. It asks first because a ticked set can move your Top set and records.']],
    food: [
      ['How was it made? (1.29)', 'After a meal photo, each cooked or put-together dish asks what a photo can’t show: what it was cooked in (which oil, butter or ghee, and how much), salt (regular, rock, black or low-sodium), pepper, sugar (white, brown, jaggery, honey or a sweetener), milk (full cream, toned, double toned, skimmed, buffalo, soy, almond or oat), sauces and dressings, cheese and cream: only what that dish has. Tap the type and the amount, or Estimate when you don’t know (the AI’s best guess); one not answered counts as the estimate. Amounts are spoons; switch to Grams at the top to type exact grams or ml. Each becomes its own line in the meal, counted from GymDay’s food list (jaggery is counted like brown sugar, which the list has), and the dish itself is counted without them. Next time the same dish starts with your last answers. Tap 🧂 How it was made under a dish to change them. Needs Meal photos: nutrients first; switch it off with Settings → More features → Ask how it was made.'],
      ['Order screenshots (1.28)', 'Ordered in? Add food → 🧾 Order (or Eating out → From an order screenshot), and pick the screenshot of your Swiggy or Zomato order or a photo of the bill. Up to 4 screenshots for a long order. The AI reads each item, then looks up its numbers at that restaurant: its own nutrition information first, then its delivery-app listing, then a nutrition database; an item it had to work out is marked “estimate”. Set each item to what you ate (halves work, “none” leaves it out) and tap Add. A screenshot shared to GymDay from your gallery asks whether it is an order or a meal photo. Takes up to a minute; one AI read.'],
      ['Which pack is better? (1.28)', 'Add food → ⚖ Compare. Take a photo of the nutrition table on two packets: GymDay shows them side by side per 100 g (or 100 ml) and ticks the better one on each line: protein for the calories, sugar (added sugar when both packs print it), saturated fat, salt and fibre, and the price of 100 g of protein when both show the MRP and weight. The verdict counts the ticks. One AI read for each pack.'],
      ['A recipe from a link (1.28)', 'Food → My recipes → 🔗 From a link, or paste a link where you paste a recipe. A recipe site or a YouTube cooking video (its description) works best; GymDay keeps the link with the recipe. Instagram and some other sites don’t open for apps: copy the recipe’s text and use Paste one instead. Up to a minute; one AI read.'],
      ['Quick Settings tiles (1.28)', 'Pull down the shade, tap ✎ (edit) and drag GymDay’s “Meal photo” or “Add food” tile in. Meal photo opens GymDay one tap from the camera; Add food opens the add-food list for the meal of the moment.'],
      ['Save a pack once (1.27)', 'A packet read off its nutrition table in a meal photo is kept in My foods by itself (for one serving when the label gives its size, otherwise for 100 g), with Undo in the message. Next time, search for it and it is one tap, with no photo. A pack already in My foods under the same name is not kept twice.'],
      ['Your usual portion (1.27)', 'When you have chosen the amount of a food yourself at least 3 times in the last 120 days (from the food list, My foods or a scan, or grams you typed or picked on a photo line), a photo or typed line of that food offers “Your usual · N g” under it when its amount is different. One tap sets it. Grams the AI guessed are never learned from.'],
      ['Best picks on a menu (1.27)', 'On a restaurant’s menu fetched from the web, the items that fit what is left of today get a ✓, and up to three best picks are at the top: the ones closest to this meal’s share of your calories left that also bring the most of the protein still to go. Calories are the menu’s own; protein is “about”, from the closest restaurant food in the food list. Nothing is marked without a daily target.'],
      ['Photos without signal (1.27)', 'Take a meal photo with no internet and GymDay offers to keep it: tap Read it when I’m online. It waits on the Food tab (“A photo is waiting to be read”), and is logged for the time you took it. When you are back online, open it: it is read and shown to you before anything is logged. Remove this photo throws it away.'],
      ['Share to GymDay (1.27)', 'In your gallery, WhatsApp or another app, tap Share on a photo of your meal and pick GymDay meal photo. GymDay opens on the Food tab and reads it like a photo taken in the app (up to 4 at once, read together).'],
      ['Fuel for today’s workout (1.27, Trainer mode)', 'With Trainer mode on, a card on Today (and at the top of What should I eat now?) says what to eat around today’s workout, timed to when you usually start (the middle start time of your last 10 workouts; it needs 3). Up to 4 hours before: a normal meal with carbs and some protein, not heavy on fat or fibre. In the last hour: something small and easy, mostly carbs. In the 3 hours after: about 0.3 g of protein for each kg you weigh (20 to 40 g), with some carbs. This follows the International Society of Sports Nutrition’s position stand on nutrient timing (2017). The foods are from your own log of the last 60 days; + Add logs one. It does not show on a rest day of your weekly plan.'],
      ['Meal photos: nutrients first (1.26)', 'When you photograph a meal, the AI now works in the order a dietitian would: what each food is, how many grams of it there are, and what 100 g of it holds (protein, carbs without the fibre, fat and fibre). GymDay then calculates the calories from those numbers: 4 kcal for each gram of protein and of carbs, 9 for fat, 2 for fibre. The AI never gives a calorie figure of its own. Each line says “From its nutrients” with its calories in 100 g; tap P · C · F to see or change the grams of each, and type the grams if you weighed it. Food list › on a line swaps it for a food from GymDay’s own list. A dish that is not in the food list is counted too now; before, it counted nothing until you picked a food. The food list is still the second opinion: when it is sure which food a line is and its calories for the same grams are far from the worked-out ones, the line says “Check this” with the list’s number, and you pick. The weight is still an estimate from a photo, so a line that looks off is worth a glance. To go back to the way it was from 1.16 to 1.25 (the AI only names the food and its weight; every number is from the food list), switch off Settings → More features → Food → Meal photos: nutrients first.'],
      ['A packet in a meal photo (1.26)', 'When the photo shows a packet with its nutrition table readable, the numbers are copied from the table, not estimated, and counted for the amount you had. The line says “From the pack’s label”, and one tap under it sets 1 serving, half the pack or the whole pack. Turn the pack so the table is in the picture; a second photo of the back is read together with the first.'],
      ['A restaurant’s menu from the web (1.25)', 'Food tab → 🍽 Eating out → A restaurant’s menu from the web. Type the restaurant, cafe or shop. GymDay’s server searches the web for the menu it serves now (its own site first, then Swiggy or Zomato) and lists it, with calories where the menu shows them. The menu is fetched the first time you open the restaurant each day, which takes up to a minute; while it comes, the menu from last time is shown. Open the same place again that day and it shows at once, at no cost. A place you don’t open is never fetched: only its name is kept, under Restaurants you have looked up, for one tap next time. At the bottom of a menu you can change this to after 2 days, a week or a month, or only when you tap Refresh. It needs you to be signed in, and each fetch counts as one of your 40 AI reads a day.'],
      ['Sizes, milk and extras (1.25)', 'Tap an item on a fetched menu, or type your order in Look it up on the web (“flat white, small, skimmed milk”). GymDay shows the item with its choices: each size with its own numbers, and what every other choice adds or takes away. Tap to change them and the calories, protein, carbs and fat follow. What you typed is already picked. Numbers the restaurant publishes are used as they are; a choice it does not publish is worked out from what goes in and marked ≈. The food is saved with its choices in its name.'],
      ['A recipe from a photo or pasted text (1.25)', 'Add food → My recipes → Photo of a recipe, From the gallery, or Paste one. The AI reads only what goes in and how much; every number is GymDay’s own, from its food list, for that weight. Check anything marked “check”, remove what is wrong, set how many servings it makes and save. It is then a food like any other.'],
      ['What can I make? (1.25)', 'In What should I eat now?, tap What can I make? and take a photo of your fridge, a shelf or your shopping. The AI lists what it can see and suggests a few dishes; GymDay counts each one from its own food list and says whether it fits what is left of today. Add to a meal opens the dish as lines you can check and change before saving.'],
      ['Protein per meal (1.25)', 'In What should I eat now?, tap Protein per meal. From your last 14 logged days it shows what each meal brings against its share of your protein target (about a quarter at breakfast and at dinner, a third at lunch). A meal well under its share is marked light, with foods you already eat that would lift it. The day’s total still matters most.'],
      ['Your usual meals (1.23)', 'An empty meal offers what you usually eat then: the foods that were in that meal on at least 4 of every 10 days you logged it in the last 4 weeks (and at least 3 times), at the amounts you last had. + Add puts them all in, with Undo. The + button offers the usual for the meal the clock says. Switch: Settings → More features → Food → Usual meals.'],
      ['What should I eat now? (1.23)', 'The button under Eating out on the Food tab. It shows the calories and protein left today, what would be a sensible size for this meal so the rest of the day still fits, and foods you logged in the last 60 days that fill it best (most of the protein left first), each with + Add. At or over your target it lists the lightest things you eat instead. They are ideas from your own log, not rules.'],
      ['Quick snap (1.23)', 'When a meal photo is clear (the reader had no questions, worked out every food with its weight, and marked nothing “Check this”), the meal is logged straight away. The message has Edit (opens the meal’s lines) and Undo. Anything less clear, and any meal eaten out, is shown to you first as before. Switch: Settings → More features → Food → Quick snap.'],
      ['My bowl, glass and spoon (1.23)', 'A katori in the food list is 150 ml, a bowl 250 ml, a glass 250 ml, a cup 240 ml, a tablespoon 15 ml and a teaspoon 5 ml. If yours are different, measure them once: fill it with water as you usually would and pour it into a measuring jug, or weigh the water (1 g is 1 ml). Settings → More features → Food → My bowl, glass and spoon, or the line under “Measured in” on any food’s amount sheet. Every food then uses your sizes; food already logged keeps its numbers.'],
      ['Oil in one dish (1.23)', 'Tap a home-cooked dish in a meal (a curry, dal, sabzi, rice dish or paratha) and its details have an Oil row: Less, Usual or More. More adds 3 g of fat to every 100 g (27 kcal); Less takes off up to 2 g. It starts on your home-cooking setting (Overview → What you eat), and a photo meal changes only its home-cooked foods. The line under it says how many calories the change makes.'],
      ['“Is this right?” for food and weight (1.23)', 'A food of 1,500 kcal or more (900 in a snack), 1.5 kg or more, or 15 or more pieces gets a yellow line under it: Yes keeps it and never asks again, Change opens it. A body weight more than 8% away from your last one, or outside 25 to 250 kg, and an activity longer than 5 hours or over 2,500 kcal, are asked about before they are saved.']],
    progress: [
      ['Next milestones (1.28)', 'History → Records shows your main lifts (the 5 you did most in the last 12 weeks) with the next round number above your heaviest set: every 5 kg up to 40 kg, then every 10 (every 10 lb up to 100, then 25), or the next 5 reps for a bodyweight move. The bar shows how far you are from the last one, and “about N weeks at your pace” comes from how your heaviest set rose over the last 12 weeks. Today shows one when you are close; each exercise’s own page shows its own.'],
      ['Your year, wrapped (1.28)', 'In December (and up to 10 January) Today shows “Your year, wrapped”: your year in GymDay card by card, your workouts, best month, longest run, most done exercise, heaviest lift, how much you lifted, favourite day and food logged, then a picture to share. Any year also has it on its Year page.'],
      ['Evening wrap-up (1.27)', 'Settings → More features → Evening wrap-up. One notification each evening at the time you choose (9:00 pm to start with): today’s workout, calories and protein against your targets, and what is on tomorrow. On a day with nothing logged it reminds you to add the day’s food, and tapping it opens the Food tab. Android must allow GymDay’s notifications.'],
      ['Every day of the year (1.25)', 'History → Progress → Year. Each small square is a day: filled when you trained, with a dot when you logged food. Under it: how many days you trained, logged food, and did both.'],
      ['This month against last month (1.25)', 'History → Progress → This month. The two months side by side: workouts, gym time, weight lifted and sets, and where you logged them protein and calories a day, sleep, steps and body weight. A month that is still running is set against the same days of the month before (1–20 against 1–20), so it is a fair comparison.'],
      ['Your month as a picture (1.25)', 'On the month page, Share as a picture makes a card with your workouts, gym time, weight lifted, the lifts that went up and your weeks in a row. Your body weight change is left off unless you turn it on in that sheet.'],
      ['Morning brief (1.25)', 'Settings → More features → Morning brief. One notification a day at the time you choose (7:00 to start with): today’s workout and your calorie target. It shows your readiness when GymDay already has last night’s sleep; before you have opened the app that morning it says to tap for it, because only the app can read your sleep.'],
      ['The Today widget (1.25)', 'Press and hold your home screen, choose Widgets, then GymDay today. It shows your readiness, the calories left today and your next workout. Like the brief, it shows readiness once the app has been opened that day.'],
      ['Readiness (1.23)', 'The Readiness ring on Today is one number from 0 to 100 for how ready you are to train, with what to do: 80 and over go heavy, 60 to 79 train as planned, 40 to 59 go lighter, under 40 rest. It is made of four parts, each scored out of 100: sleep last night against what you need (35%), how recovered the muscles of your next workout are (30%), resting heart rate and HRV against your usual (20%), and yesterday’s protein and calories (15%). A part with nothing logged is left out and the others share its weight. Tap the ring to see each part. It is an estimate: how you feel comes first.'],
      ['Patterns (1.23)', 'A card on Today and a page under History → Progress → Patterns. GymDay looks through your own log, on your phone, for things that are easy to miss: protein or calories that change at weekends, how often you reach your protein target, short sleep, a lift going up, lifts that are stuck, a body part falling behind, how often you reach your weekly goal, days with no food logged. Each needs enough days before it says anything, and each shows its numbers and how it was worked out when you tap it. Switch: Settings → More features → Progress → Patterns.'],
      ['Goal dates (1.23)', 'Set a goal weight on the Body weight page and GymDay says when you would reach it at your pace: a straight line through your weigh-ins of the last 4 weeks (it needs at least 4 over 10 days). An exercise with a goal says the same on its page, from the heaviest set of each workout in the last 8 weeks. The date moves as you log. GymDay gives no date for losing weight under 18, nor for a goal under a healthy weight for your height.']],
    watch: [
      ['Sleep from your watch (1.32)', 'Tap ⌚ Get it from your watch on Today’s “Last night’s sleep” card (or ⌚ From your watch in Recovery), and pick your watch once. GymDay then shows the easiest way for it. OnePlus (OHealth) and Samsung Galaxy watches share sleep with Health Connect: switch on Health Connect in their app, then Turn on automatic, and last night comes in by itself each morning. Noise, boAt and Fire-Boltt apps often don’t share sleep with Health Connect, so take a screenshot of last night in their app and choose it: GymDay reads the numbers. On an iPhone it is Apple Health: an Apple Watch and NoiseFit share sleep there. A screenshot works with every watch, and you can always type it.'],
      ['Automatic from your watch (1.24)', 'Settings → Watch & Google Health → Automatic from your watch. Health Connect then asks what GymDay may read: sleep, resting heart rate, heart rate variability, blood oxygen, breathing rate, steps and calories. Allow what you like. After that, whenever you open GymDay it brings in last night’s sleep (with its stages, bedtime and wake-up), the night’s heart numbers, and the day’s steps and calories, for today and the two days before, since watches often send things late. No screenshots are needed. It only reads; nothing is changed in Health Connect.'],
      ['Automatic: which numbers win (1.24)', 'Yours, always. A number you typed, or read from screenshots, is never replaced: Health Connect only fills what is empty and keeps refreshing what it filled in itself. If you remove a day’s numbers or clear a night, they are not brought in again behind your back; the card then offers “Bring it in again”.'],
      ['Automatic: how the calories are counted (1.24)', 'Your watch’s total for the day is used when its resting part looks like a body’s (GymDay compares it with your own resting burn from About me). If it does not, only the active calories are used, on top of your resting burn. A total with no heart rate behind it is ignored: Android can estimate one with no watch at all. Today is counted up to the newest thing your watch sent, and the rest of the day at your usual pace, so Burnt and “kcal left” stay sensible between syncs. A workout your watch already saw is not counted twice.'],
      ['Automatic: nothing comes in (1.24)', 'Your watch’s own app (Samsung Health, Fitbit, Garmin Connect, Zepp, Mi Fitness and others) has to be set to share with Health Connect: look for Health Connect in that app’s settings. Then check in Health Connect that GymDay is allowed to read each kind. Settings → Watch & Google Health shows when GymDay last brought things in and what is not allowed yet; “Bring in now” looks again at once. Sleep score is not something Health Connect carries, so type it if you want it.']],
    data: [
      ['Recently deleted (1.23)', 'Anything you delete on this phone (a workout, a food, a day, a weigh-in, an activity, a recipe) waits 30 days under Settings → Backup & export → Recently deleted. Put back brings it back exactly as it was, on your other phones too; photos are not kept. What a sync removed, a restored backup replaced, or “Delete all my data” wiped is not kept there.']],
  };
  HELP.forEach(sec => { if (MORE[sec[0]]) sec[3].push(...MORE[sec[0]]); });
  // 1.35.2: Help reads as help, not a change log: no version numbers in the questions or answers ("Voice logging (1.20)"),
  // and the answers that only said what changed in a version are left out (What's new has those)
  const NEWS_ONLY = ['The new look on other pages (1.27)', 'The new Settings (1.26)', 'GymDay’s own dropdowns (1.28)'];
  const plainQ = q => window.__calm === false ? String(q) : String(q).replace(/\s*\(v?1\.\d+(?:\.\d+)?(?:,\s*([^)]*))?\)\s*$/, (m, g) => (g ? ` (${g})` : ''));
  const plainA = a => window.__calm === false ? String(a) : String(a).replace(/\s*\((?:v|since |new in )?1\.\d+(?:\.\d+)?(?:,\s*([^)]*))?\)/g, (m, g) => (g ? ` (${g})` : '')).replace(/\s{2,}/g, ' ');
  VIEWS.help = {
    html({ s, i } = {}) {
      const at = i > 0 ? i : 0;
      return `<div class="top"><button class="back" data-act="back">‹</button><div class="grow"><h1>Help & tips</h1><div class="sub">How GymDay works, in plain words</div></div></div>
        ${HELP.map(([id, ic, title, qs]) => `<div class="card help-s" id="help-${id}"><h3 class="help-h"><span class="help-ic">${ic}</span>${esc(title)}</h3>
          ${qs.map(([q, a], i) => `<details class="help-q"${id === s && i === at ? ' open id="help-at"' : ''}${shown(id, i) && (window.__calm === false || !NEWS_ONLY.includes(q)) ? '' : ' hidden'}><summary>${esc(plainQ(q))}</summary><p>${esc(plainA(a))}</p></details>`).join('')}</div>`).join('')}
        <button class="btn block" data-act="tipsAgain">Show the tips again</button>
        <p class="xs dim mt12" style="text-align:center">GymDay ${esc((window.GYMDAY_APP || {}).name || '')}</p>`;
    },
    mount({ s, i } = {}) { if (s) setTimeout(() => { const el = (i > 0 && $('#help-at')) || $('#help-' + s); if (el) el.scrollIntoView({ block: i > 0 ? 'center' : 'start' }); }, 30); }
  };
  // 1.33: without a watch (watch.js) the watch section keeps only its first answer, the one about the switch, and the answers
  // elsewhere that are only about a watch are left out too
  const WATCH_ONLY = ['Forgot to log? Ask my watch', 'Your day, from your watch', 'Workout screenshots', 'Sleep & heart'];
  const shown = (id, i) => {
    if (!window.Watch || window.Watch.on()) return true;
    if (id === 'watch') return i === 0;
    const sec = HELP.find(x => x[0] === id), q = sec && sec[3][i] ? sec[3][i][0] : '';
    return !WATCH_ONLY.some(w => q.startsWith(w));
  };
  ACT.helpOpen = el => A.go('help', { s: (el && el.dataset && el.dataset.s) || '' });
  ACT.tipsAgain = () => { const m = M(); m.tips = {}; if (S.saveMeta) S.saveMeta(); window.toast('The tips will show again on each screen'); };

  window.Help = { TIPS, HELP, tipHtml, shown };
})();
